// Hand-written `amqplib` stub for the flowatlas fixture suite. It declares only
// what `fixtures/nest-rabbitmq/src` touches, in the real library's shape.
//
// `amqplib` is the detection key for the `nestjs-rabbitmq` adapter (§7). In a
// real repo it is a transitive dependency of `@golevelup/nestjs-rabbitmq` that
// the application still imports directly for the raw message and option types,
// which is exactly how it is used here: as parameter types on the
// `@RabbitSubscribe` handlers, never as a call receiver.

export namespace Options {
  export interface Publish {
    persistent?: boolean;
    expiration?: string | number;
    messageId?: string;
    headers?: Record<string, unknown>;
  }

  export interface AssertQueue {
    durable?: boolean;
    exclusive?: boolean;
  }
}

export interface ConsumeMessage {
  content: Uint8Array;
  fields: {
    exchange: string;
    routingKey: string;
    deliveryTag: number;
    redelivered: boolean;
  };
  properties: {
    messageId?: string;
    correlationId?: string;
    headers: Record<string, unknown>;
  };
}

export interface Channel {
  assertExchange(exchange: string, type: string, options?: unknown): Promise<unknown>;
  assertQueue(queue: string, options?: Options.AssertQueue): Promise<unknown>;
  bindQueue(queue: string, exchange: string, routingKey: string): Promise<unknown>;
}

export interface Connection {
  createChannel(): Promise<Channel>;
  close(): Promise<void>;
}

export declare function connect(url: string): Promise<Connection>;
